// Generated by GitHub Copilot
import { useEffect, useRef, useState } from 'react';
import { BleCentral, type ScanResultEvent } from '../../ble/central';
import { isNative } from '../../ble/peripheral';
import { createAck, decodeIntent, encodeMessage, isExpired } from '../../protocol/codec';
import type { PaymentIntent } from '../../protocol/types';
import {
  HELLO_PROBE,
  aesGcmDecrypt,
  aesGcmEncrypt,
  b64decode,
  b64encode,
  decodeSecureEnvelope,
  deriveSessionKey,
  encodeSecureEnvelope,
  exportPubRaw,
  generateEphemeralKeyPair,
  importPubRaw,
  type SecureEnvelope,
  type SecureHello
} from '../../protocol/secure';
import { applyAck, markStatus, upsertFromIntent, wasSeen } from '../../storage/ledger';
import { logger } from '../logger';

/**
 * "Pagar" — payer side. Flujo nuevo:
 *  1) Lista en vivo de puestos cercanos (BLEPay-XXXX) ordenados por RSSI.
 *  2) Usuario ingresa el PIN visible en el puesto y toca el item correcto.
 *  3) Conecta al address elegido, lee el envelope `hello`, deriva clave con el
 *     PIN ingresado y manda `hello_ack`. Si el PIN es incorrecto el handshake
 *     falla con auth tag inválida — no hay confusión silenciosa.
 *  4) Recibe `sec_intent` cifrado, valida y muestra. Confirma → `sec_ack`.
 */
const PROBE_BYTES = new TextEncoder().encode(HELLO_PROBE);
const STALE_MS = 6_000;

interface DiscoveredStall {
  address: string;
  name: string;
  rssi: number;
  lastSeen: number;
}

export function PayMode() {
  const [busy, setBusy] = useState(false);
  const [stage, setStage] = useState<string>('idle');
  const [scanning, setScanning] = useState(false);
  const [pinInput, setPinInput] = useState('');
  const [stalls, setStalls] = useState<DiscoveredStall[]>([]);
  const [intent, setIntent] = useState<PaymentIntent | null>(null);

  const helloRef = useRef<SecureHello | null>(null);
  const myKpRef = useRef<{ publicKey: CryptoKey; privateKey: CryptoKey } | null>(null);
  const sessionKeyRef = useRef<CryptoKey | null>(null);
  const pinRef = useRef<string>('');
  const nativeListenersRef = useRef<Array<{ remove: () => Promise<void> }>>([]);
  const nativeConnectedRef = useRef<boolean>(false);
  const stallsMapRef = useRef<Map<string, DiscoveredStall>>(new Map());
  const pruneIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      cleanup().catch(() => undefined);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function refreshStalls() {
    const now = Date.now();
    const arr: DiscoveredStall[] = [];
    for (const s of stallsMapRef.current.values()) {
      if (now - s.lastSeen <= STALE_MS) arr.push(s);
    }
    arr.sort((a, b) => b.rssi - a.rssi);
    setStalls(arr);
  }

  async function cleanup() {
    if (pruneIntervalRef.current != null) {
      window.clearInterval(pruneIntervalRef.current);
      pruneIntervalRef.current = null;
    }
    const list = nativeListenersRef.current.splice(0);
    await Promise.all(list.map((l) => l.remove().catch(() => undefined)));
    if (isNative()) {
      await BleCentral.stopScan().catch(() => undefined);
      if (nativeConnectedRef.current) {
        await BleCentral.disconnect().catch(() => undefined);
        nativeConnectedRef.current = false;
      }
    }
    sessionKeyRef.current = null;
    helloRef.current = null;
    myKpRef.current = null;
    pinRef.current = '';
    stallsMapRef.current.clear();
  }

  async function onIntentUpdate(bytes: Uint8Array) {
    try {
      const env = decodeSecureEnvelope(bytes);
      if (env.kind !== 'sec_intent') {
        logger.debug('protocol', `intent_update kind=${env.kind} ignorado`);
        return;
      }
      const key = sessionKeyRef.current;
      if (!key) {
        logger.warn('protocol', 'sec_intent recibido sin clave de sesión');
        return;
      }
      const plain = await aesGcmDecrypt(key, b64decode(env.iv), b64decode(env.ct));
      const pi = await decodeIntent(plain);

      if (await wasSeen(pi.tx_id)) {
        throw new Error(`tx_id repetido (${pi.tx_id}).`);
      }
      if (isExpired(pi)) {
        await upsertFromIntent(pi, 'payer', 'CREATED', 'intent recibido pero expirado');
        await markStatus(pi.tx_id, 'EXPIRED', 'TTL vencido al recibir');
        throw new Error('Intent expirado.');
      }
      await upsertFromIntent(pi, 'payer', 'CREATED', 'intent cifrado leído');
      setIntent(pi);
      setStage('listo para confirmar');
    } catch (e) {
      const msg = (e as Error).message;
      logger.error('protocol', `sec_intent inválido: ${msg}`);
      setStage(`error: ${msg}`);
    }
  }

  async function startDiscovery() {
    if (!isNative()) {
      setStage('Modo seguro v1 sólo soportado en APK por ahora.');
      return;
    }
    setBusy(true);
    setStage('iniciando escaneo');
    setStalls([]);
    stallsMapRef.current.clear();
    setIntent(null);
    sessionKeyRef.current = null;
    try {
      const av = await BleCentral.isAvailable();
      if (!av.available) throw new Error(`BLE central no disponible: ${av.reason ?? 'desconocido'}`);

      // Listeners (idempotente: si ya estaban, los recreamos en cada start).
      if (nativeListenersRef.current.length === 0) {
        const stateL = await BleCentral.addListener('state', (data) => {
          const s = data as { stage?: string; message?: string };
          if (s?.stage) logger.info('notify', `central: ${s.stage} ${s.message ?? ''}`);
        });
        const updateL = await BleCentral.addListener('intent_update', (data) => {
          const payload = data as { intentBase64?: string };
          if (!payload?.intentBase64) return;
          void onIntentUpdate(b64decode(payload.intentBase64));
        });
        const scanL = await BleCentral.addListener('scan_result', (data) => {
          const r = data as ScanResultEvent;
          if (!r?.address) return;
          stallsMapRef.current.set(r.address, {
            address: r.address,
            name: r.name || '(sin nombre)',
            rssi: r.rssi,
            lastSeen: r.timestamp || Date.now()
          });
          refreshStalls();
        });
        nativeListenersRef.current.push(stateL, updateL, scanL);
      }

      pruneIntervalRef.current = window.setInterval(refreshStalls, 1500);
      setScanning(true);
      void BleCentral.scanList({ timeoutMs: 60_000 }).then((res) => {
        if (res.reason === 'timeout') {
          setScanning(false);
          setStage('escaneo finalizado (timeout)');
        }
      }).catch((e: unknown) => {
        setScanning(false);
        setStage(`error scan: ${(e as Error).message}`);
      });
      setStage('elegí el puesto e ingresá el PIN');
    } catch (e) {
      const msg = (e as Error).message;
      logger.error('ui', `Pagar(scan): ${msg}`);
      setStage(`error: ${msg}`);
    } finally {
      setBusy(false);
    }
  }

  async function pickStall(stall: DiscoveredStall) {
    if (!/^\d{4,9}$/.test(pinInput)) {
      setStage('Primero ingresá el PIN (4–9 dígitos).');
      return;
    }
    pinRef.current = pinInput;
    setBusy(true);
    setStage(`conectando a ${stall.name}`);
    try {
      // Stop scan and connect to the chosen device.
      setScanning(false);
      await BleCentral.stopScan().catch(() => undefined);

      const res = await BleCentral.connectByAddress({ address: stall.address });
      nativeConnectedRef.current = true;

      const env = decodeSecureEnvelope(b64decode(res.intentBase64));
      if (env.kind !== 'hello') throw new Error(`Esperaba kind=hello, vino ${env.kind}`);
      helloRef.current = env;

      // Generate our ephemeral keypair + derive session key right away.
      const kp = await generateEphemeralKeyPair();
      myKpRef.current = kp;
      const receiverPub = await importPubRaw(b64decode(env.receiver_pub));
      const salt = b64decode(env.salt);
      const key = await deriveSessionKey(kp.privateKey, receiverPub, salt, pinRef.current);
      sessionKeyRef.current = key;

      // Build hello_ack with encrypted probe.
      const myPubBytes = await exportPubRaw(kp.publicKey);
      const { iv, ct } = await aesGcmEncrypt(key, PROBE_BYTES);
      const helloAck: SecureEnvelope = {
        v: 1, kind: 'hello_ack',
        payer_pub: b64encode(myPubBytes),
        iv: b64encode(iv),
        ct: b64encode(ct)
      };
      await BleCentral.writeAck({ ackBase64: b64encode(encodeSecureEnvelope(helloAck)) });
      setStage('handshake enviado, esperando intent cifrado…');
    } catch (e) {
      const msg = (e as Error).message;
      logger.error('ui', `Pagar(connect): ${msg}`);
      setStage(`error: ${msg}`);
      sessionKeyRef.current = null;
      if (nativeConnectedRef.current) {
        await BleCentral.disconnect().catch(() => undefined);
        nativeConnectedRef.current = false;
      }
    } finally {
      setBusy(false);
    }
  }

  async function onConfirm(result: 'OK' | 'REJECT') {
    if (!intent) return;
    const key = sessionKeyRef.current;
    if (!key) {
      setStage('error: sin clave de sesión');
      return;
    }
    setBusy(true);
    setStage(result === 'OK' ? 'pagando' : 'rechazando');
    try {
      const ack = await createAck(intent, result, result === 'REJECT' ? 'usuario rechazó' : undefined);
      const ackBytes = encodeMessage(ack);
      const { iv, ct } = await aesGcmEncrypt(key, ackBytes);
      const env: SecureEnvelope = {
        v: 1, kind: 'sec_ack', iv: b64encode(iv), ct: b64encode(ct)
      };
      await BleCentral.writeAck({ ackBase64: b64encode(encodeSecureEnvelope(env)) });
      await applyAck(ack, `ack cifrado: ${result}`);
      setStage(result === 'OK' ? 'pagado' : 'rechazado');
      logger.info('protocol', `ACK ${result} enviado para ${intent.tx_id}`);
    } catch (e) {
      const msg = (e as Error).message;
      logger.error('ui', `Pagar(confirm): ${msg}`);
      await markStatus(intent.tx_id, 'FAILED', `error al enviar ack: ${msg}`);
      setStage(`error: ${msg}`);
    } finally {
      setBusy(false);
    }
  }

  async function onCancel() {
    await cleanup();
    setIntent(null);
    setPinInput('');
    setStalls([]);
    setScanning(false);
    setStage('cancelado');
  }

  function rssiBars(rssi: number): string {
    // Rough mapping: -50 strong, -90 weak.
    if (rssi >= -55) return '████';
    if (rssi >= -65) return '███░';
    if (rssi >= -75) return '██░░';
    if (rssi >= -85) return '█░░░';
    return '░░░░';
  }

  return (
    <div className="card">
      <h2>
        Pagar{' '}
        {isNative()
          ? <span className="muted">(seguro v1 · ECDH+PIN)</span>
          : <span className="muted">(no disponible en PWA)</span>}
      </h2>
      <p className="muted">
        Mirá el cartelito del puesto: te muestra <strong>BLEPay-XXXX</strong> y
        un <strong>PIN</strong>. Ingresá el PIN, después tocá el puesto en la
        lista. Si elegís mal o el PIN no coincide, la conexión falla — no se
        completa ningún cobro accidental.
      </p>

      <label htmlFor="pin-input">PIN del puesto</label>
      <input
        id="pin-input"
        type="text"
        inputMode="numeric"
        autoComplete="off"
        value={pinInput}
        maxLength={9}
        onChange={(e) => setPinInput(e.target.value.replace(/\D/g, ''))}
        disabled={busy || !!intent}
        aria-describedby="pin-help"
        style={{ fontSize: 24, letterSpacing: 4, fontFamily: 'monospace' }}
      />
      <p id="pin-help" className="muted">4 a 9 dígitos.</p>

      <div className="row">
        <button
          className="primary"
          onClick={startDiscovery}
          disabled={busy || scanning || !!intent}
        >
          {scanning ? 'Escaneando…' : 'Buscar puestos'}
        </button>
        <button
          className="secondary"
          onClick={onCancel}
          disabled={busy && !scanning}
        >
          Cancelar
        </button>
      </div>

      {!intent && (
        <ul
          aria-label="Puestos cercanos"
          style={{
            listStyle: 'none', padding: 0, marginTop: 12,
            maxHeight: 280, overflowY: 'auto'
          }}
        >
          {stalls.length === 0 && scanning && (
            <li className="muted" style={{ padding: 12 }}>Buscando…</li>
          )}
          {stalls.map((s) => (
            <li key={s.address}>
              <button
                onClick={() => pickStall(s)}
                disabled={busy || pinInput.length < 4}
                aria-label={`Puesto ${s.name}, señal ${s.rssi} dBm, dirección ${s.address}`}
                style={{
                  display: 'flex', justifyContent: 'space-between',
                  width: '100%', padding: 12, marginBottom: 4,
                  background: '#1a2c44', color: '#eaf2ff',
                  border: '1px solid #2a4a70', borderRadius: 6,
                  fontSize: 16, textAlign: 'left', cursor: 'pointer'
                }}
              >
                <span style={{ fontFamily: 'monospace', fontWeight: 600 }}>{s.name}</span>
                <span className="muted" aria-hidden="true">
                  {rssiBars(s.rssi)} {s.rssi} dBm
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}

      {intent && (
        <div style={{ marginTop: 12 }}>
          <p>
            <strong>{(intent.amount / 100).toFixed(2)} {intent.currency}</strong>
            {intent.memo ? <> — <em>{intent.memo}</em></> : null}
          </p>
          <p className="muted">tx_id: <span className="kbd">{intent.tx_id}</span></p>
          <div className="row">
            <button className="primary" onClick={() => onConfirm('OK')} disabled={busy}>
              Confirmar pago
            </button>
            <button className="secondary" onClick={() => onConfirm('REJECT')} disabled={busy}>
              Rechazar
            </button>
          </div>
        </div>
      )}

      <p className="muted" aria-live="polite">Estado: {stage}</p>
    </div>
  );
}
